import{_ as e,o as n,c as t,a5 as s}from"./chunks/framework.Bqo7-qSd.js";const u=JSON.parse('{"title":"子程序调用（call / return）","description":"","frontmatter":{"title":"子程序调用（call / return）","order":9},"headers":[],"relativePath":"zh/latest/tutorial/script/call-and-return.md","filePath":"zh/latest/tutorial/script/call-and-return.md","lastUpdated":1795484315000}'),l={name:"zh/latest/tutorial/script/call-and-return.md"};function c(o,a,i,p,r,d){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="子程序调用-call-return" tabindex="-1">子程序调用（call / return） <a class="header-anchor" href="#子程序调用-call-return" aria-label="Permalink to &quot;子程序调用（call / return）&quot;">​</a></h1><h2 id="功能描述" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述" aria-label="Permalink to &quot;功能描述&quot;">​</a></h2><p><code>call</code> 把当前剧本里的一个 <code>branch</code> 当作子程序调用：进入分支执行，遇到 <code>return</code> 时回到 <code>call</code> 的下一行继续。</p><ul><li>与 <code>jump_branch</code> 的区别：<code>jump_branch</code> 是尾跳转，不会回来；<code>call</code> 会把返回点压入调用栈。</li><li>与 <code>jump</code> 的区别：<code>jump</code> 切换剧本（镜头），并清空尚未 <code>return</code> 的调用栈；跨剧本调用暂不支持。</li><li>调用栈属于运行期状态，会随“上一句”回退、检查点与存档一起保存和恢复。</li><li>编译期会拒绝递归调用（直接或间接），并限制最大调用链长度（256 层）。</li><li>调用栈为空时执行 <code>return</code> 等价于 <code>end</code>（结束当前镜头）。</li></ul><h2 id="语法结构" tabindex="-1">语法结构 <a class="header-anchor" href="#语法结构" aria-label="Permalink to &quot;语法结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>call &lt;branch_name&gt;</span></span>
<span class="line"><span>return</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>branch_name</td><td>是</td><td><code>gift_scene</code></td><td>当前剧本内已声明的分支标识符</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>call gift_scene</span></span>
<span class="line"><span>Kona &quot;回到调用点之后。&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch gift_scene</span></span>
<span class="line"><span>	Kona &quot;这里是公用桥段。&quot;</span></span>
<span class="line"><span>	return</span></span></code></pre></div><p>嵌套调用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>call chapter_intro</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch chapter_intro</span></span>
<span class="line"><span>	Kona &quot;第一章开始。&quot;</span></span>
<span class="line"><span>	call phone_ring</span></span>
<span class="line"><span>	Kona &quot;第一章结束。&quot;</span></span>
<span class="line"><span>	return</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch phone_ring</span></span>
<span class="line"><span>	Kona &quot;电话响了。&quot;</span></span>
<span class="line"><span>	return</span></span></code></pre></div><h2 id="被调分支的结束方式" tabindex="-1">被调分支的结束方式 <a class="header-anchor" href="#被调分支的结束方式" aria-label="Permalink to &quot;被调分支的结束方式&quot;">​</a></h2><ul><li>显式 <code>return</code>：最清晰，回到调用点。</li><li>分支自然结束：会接到编译器生成的 <code>halt</code>，等同于结束整个镜头。因此<strong>被调用的分支建议显式写 <code>return</code></strong>。</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><code>call</code> 的目标必须是当前剧本内的分支；跨剧本请使用 <code>jump</code>。</li><li><code>call</code> 不能形成递归（包括间接递归），否则编译失败。</li><li><code>jump</code> 会丢弃当前镜头未返回的调用帧；不要依赖跨镜头的 <code>return</code>。</li><li>选项、分支与条件块中都可以使用 <code>call</code> 与 <code>return</code>。</li><li>运行时错误恢复面板对 <code>call</code> 只提供“重试/停止”，不提供“跳过”：跳过会进入没有返回帧的分支。</li></ol>`,16)])])}const b=e(l,[["render",c]]);export{u as __pageData,b as default};
